    {
      "a_request": "R1",
      "b_asked": "학교에 짓는 부설주차장의 최대 한도가 이 주차장 조례로 정해지는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "학교에 설치하는 부설주차장의 최고한도는 이 조례(제21조의2)에서 직접 정하지 않고, 「서울특별시교육청 학교 주차장 관리에 관한 조례」로 따로 정하도록 규정되어 있다. 따라서 학교에 짓는 부설주차장의 최대 한도는 이 주차장 조례가 아니라 해당 교육청 조례로 정해진다.",
          "b_ids": "주차장:제21조의2"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
